import{_ as e,o as l,c as o,a0 as d}from"./chunks/framework.jwovEGr5.js";const f=JSON.parse('{"title":"管理員權限與維護指南","description":"","frontmatter":{},"headers":[],"relativePath":"Mc-Admin-Management.md","filePath":"Mc-Admin-Management.md"}'),a={name:"Mc-Admin-Management.md"};function r(n,t,s,c,i,g){return l(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="管理員權限與維護指南" tabindex="-1">管理員權限與維護指南 <a class="header-anchor" href="#管理員權限與維護指南" aria-label="Permalink to &quot;管理員權限與維護指南&quot;">​</a></h1><p>本指南列出 Craft-Core 伺服器管理員專用的遊戲內指令、Ledger 方塊紀錄查詢回滾系統，以及 Discord 管理員控制面板說明。</p><hr><h2 id="_1-ledger-lg-方塊紀錄查詢與回滾還原系統" tabindex="-1">1. /ledger (/lg) 方塊紀錄查詢與回滾還原系統 <a class="header-anchor" href="#_1-ledger-lg-方塊紀錄查詢與回滾還原系統" aria-label="Permalink to &quot;1. /ledger (/lg) 方塊紀錄查詢與回滾還原系統&quot;">​</a></h2><p>伺服器配備了強大的 <strong>Ledger 方塊與防破壞紀錄系統</strong>，管理員可透過 <code>/ledger</code>（快捷別名 <code>/lg</code>）隨時查詢方塊歷史變動或進行一鍵復原。</p><h3 id="🔍-檢查模式-inspect-mode" tabindex="-1">🔍 檢查模式 (Inspect Mode) <a class="header-anchor" href="#🔍-檢查模式-inspect-mode" aria-label="Permalink to &quot;🔍 檢查模式 (Inspect Mode)&quot;">​</a></h3><ul><li><strong><code>/lg inspect</code></strong> 或 <strong><code>/lg inspect [on|off]</code></strong>：開啟或關閉檢查模式。</li><li><strong>使用方式</strong>：開啟檢查模式後，對著目標方塊按**【左鍵】<strong>或</strong>【右鍵】**，聊天欄會即時顯示該方塊是誰在什麼時間點放置、破壞，或是誰拿走了容器內的物品。</li></ul><h3 id="🔎-日誌搜尋-search" tabindex="-1">🔎 日誌搜尋 (Search) <a class="header-anchor" href="#🔎-日誌搜尋-search" aria-label="Permalink to &quot;🔎 日誌搜尋 (Search)&quot;">​</a></h3><ul><li><strong><code>/lg search &lt;參數&gt;</code></strong>：依據條件搜尋記錄而不進行變更。</li><li><strong>範例</strong>：<code>/lg search source:Alex time:1h range:10</code>（查詢玩家 Alex 在近 1 小時內於 10 格範圍內的所有動作）。</li></ul><h3 id="↩️-一鍵回滾還原-rollback" tabindex="-1">↩️ 一鍵回滾還原 (Rollback) <a class="header-anchor" href="#↩️-一鍵回滾還原-rollback" aria-label="Permalink to &quot;↩️ 一鍵回滾還原 (Rollback)&quot;">​</a></h3><ul><li><strong><code>/lg rollback &lt;參數&gt;</code></strong>：依據條件將指定範圍內被破壞或變更的方塊一鍵恢復至原狀。</li><li><strong>範例</strong>：<code>/lg rollback source:BadPlayer time:2h range:20</code>（將近 2 小時內被 BadPlayer 在 20 格內破壞的方塊全部還原）。</li></ul><h3 id="🛠️-常用過濾參數說明" tabindex="-1">🛠️ 常用過濾參數說明 <a class="header-anchor" href="#🛠️-常用過濾參數說明" aria-label="Permalink to &quot;🛠️ 常用過濾參數說明&quot;">​</a></h3><ul><li><strong><code>source:&lt;玩家/實體&gt;</code></strong>：指定操作者名稱（如 <code>source:Alex</code> 或爆炸來源 <code>source:tnt</code>）。</li><li><strong><code>time:&lt;時間&gt;</code></strong>：指定時間範圍（如 <code>1h</code> 一小時內、<code>1d</code> 一天內）。</li><li><strong><code>range:&lt;距離&gt;</code></strong>：指定管理員身邊半徑內的範圍格數（如 <code>range:15</code>）。</li><li><strong><code>action:&lt;動作&gt;</code></strong>：指定動作類型（如 <code>block-break</code> 破壞方塊、<code>block-place</code> 放置方塊、<code>container-change</code> 容器物品存取）。</li></ul><h3 id="🔄-撤銷與取消操作" tabindex="-1">🔄 撤銷與取消操作 <a class="header-anchor" href="#🔄-撤銷與取消操作" aria-label="Permalink to &quot;🔄 撤銷與取消操作&quot;">​</a></h3><ul><li><strong><code>/lg undo</code></strong> 或 <strong><code>/lg restore</code></strong>：若還原範圍設定有誤，可一鍵撤銷上一次的回滾復原動作。</li></ul><hr><h2 id="_2-遊戲內管理員專用指令" tabindex="-1">2. 遊戲內管理員專用指令 <a class="header-anchor" href="#_2-遊戲內管理員專用指令" aria-label="Permalink to &quot;2. 遊戲內管理員專用指令&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">指令</th><th style="text-align:left;">功能說明</th><th style="text-align:left;">範例與備註</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>/addmoney &lt;玩家&gt; &lt;金額&gt;</code></strong></td><td style="text-align:left;">增加指定玩家的遊戲金幣餘額</td><td style="text-align:left;"><code>/addmoney Alex 5000</code></td></tr><tr><td style="text-align:left;"><strong><code>/removemoney &lt;玩家&gt; &lt;金額&gt;</code></strong></td><td style="text-align:left;">扣除指定玩家的遊戲金幣餘額</td><td style="text-align:left;"><code>/removemoney Alex 1000</code></td></tr><tr><td style="text-align:left;"><strong><code>/check &lt;金額&gt;</code></strong></td><td style="text-align:left;">開立具防偽標籤之實體紙張支票面交/發放</td><td style="text-align:left;"><code>/check 10000</code></td></tr><tr><td style="text-align:left;"><strong><code>/treasure spawn</code></strong></td><td style="text-align:left;">強制清除舊寶箱並於地表刷新野外神秘寶箱</td><td style="text-align:left;"><code>/treasure spawn</code></td></tr><tr><td style="text-align:left;"><strong><code>/setwarp &lt;地標名稱&gt;</code></strong></td><td style="text-align:left;">在當前位置建立公共地標</td><td style="text-align:left;"><code>/setwarp spawn</code></td></tr><tr><td style="text-align:left;"><strong><code>/delwarp &lt;地標名稱&gt;</code></strong></td><td style="text-align:left;">刪除指定的公共地標</td><td style="text-align:left;"><code>/delwarp spawn</code></td></tr><tr><td style="text-align:left;"><strong><code>/invsee &lt;玩家&gt;</code></strong></td><td style="text-align:left;">查看與編輯線上玩家或假人的背包與裝備箱</td><td style="text-align:left;"><code>/invsee Alex</code></td></tr><tr><td style="text-align:left;"><strong><code>/ban &lt;玩家&gt; [原因]</code></strong></td><td style="text-align:left;">封鎖指定玩家並禁止登入</td><td style="text-align:left;"><code>/ban BadUser 破壞地形</code></td></tr><tr><td style="text-align:left;"><strong><code>/kick &lt;玩家&gt; [原因]</code></strong></td><td style="text-align:left;">強制踢出指定線上玩家</td><td style="text-align:left;"><code>/kick AFKUser 佔用伺服器</code></td></tr><tr><td style="text-align:left;"><strong><code>/shop list</code></strong></td><td style="text-align:left;">列出全服所有註冊商店</td><td style="text-align:left;"><code>/shop list</code></td></tr><tr><td style="text-align:left;"><strong><code>/shop reload</code></strong></td><td style="text-align:left;">重新載入商店設定與資料</td><td style="text-align:left;"><code>/shop reload</code></td></tr></tbody></table><hr><h2 id="_3-管理員無限系統商店" tabindex="-1">3. 管理員無限系統商店 <a class="header-anchor" href="#_3-管理員無限系統商店" aria-label="Permalink to &quot;3. 管理員無限系統商店&quot;">​</a></h2><p>管理員可建立免庫存、免資金的官方系統商店：</p><ol><li>建立商店後，對著商店告示牌按**【右鍵】**開啟管理面板。</li><li>管理員可看見**「切換無限」**按鈕，點擊後庫存將切換為無限模式，玩家可自由買賣。</li><li>對著無限商店面板點選**「清空箱子」**按鈕，可快速清空實體箱子內的殘留物品。</li></ol><hr><h2 id="_4-discord-管理員控制面板" tabindex="-1">4. Discord 管理員控制面板 <a class="header-anchor" href="#_4-discord-管理員控制面板" aria-label="Permalink to &quot;4. Discord 管理員控制面板&quot;">​</a></h2><p>管理員可於 Discord 專屬維護頻道中使用以下快捷面板：</p><ul><li><strong>封鎖/踢出玩家</strong>：填寫玩家 ID 與理由發送處分。</li><li><strong>發布全服公告</strong>：預覽並發布彩色全服公告訊息。</li><li><strong>公共設施審核</strong>：審核玩家提交的設施申請，點擊同意後自動設立 <code>/warp</code> 地標。</li></ul>',26)])])}const x=e(a,[["render",r]]);export{f as __pageData,x as default};
